SELECT JSON_ARRAY('cycle_histories', id, user_id, period_start_date, period_end_date, cycle_length, bleeding_length, is_confirmed, is_estimated, source, data_quality_flags, created_at, updated_at) FROM cycle_histories WHERE user_id IN (1001, 1002, 1003, 1004, 1005, 1007, 1008, 1010) ORDER BY user_id, period_start_date;
SELECT JSON_ARRAY('user_profiles', id, user_id, last_period_start, calculation_status, calculation_started_at, calculation_completed_at, calculation_version, created_at, updated_at) FROM user_profiles WHERE user_id IN (1001, 1002, 1003, 1004, 1005, 1007, 1008, 1010) ORDER BY id;
